using Microsoft.ML.Data;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
if (!File.Exists(dataPath))
    dataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "tickets.csv");

var classifier = new TicketClassifierService(dataPath);
builder.Services.AddSingleton(classifier);

// Evaluate and log metrics at startup
var metrics = classifier.Evaluate(dataPath);
LogMetrics(metrics);

var app = builder.Build();
app.MapControllers();
app.Run();

static void LogMetrics(MulticlassClassificationMetrics metrics)
{
    Console.WriteLine("=== Model Evaluation Metrics ===");
    Console.WriteLine($"  Macro Accuracy:    {metrics.MacroAccuracy:P2}");
    Console.WriteLine($"  Micro Accuracy:    {metrics.MicroAccuracy:P2}");
    Console.WriteLine($"  Log Loss:          {metrics.LogLoss:F4}");
    Console.WriteLine($"  Log Loss Reduction:{metrics.LogLossReduction:F4}");
    Console.WriteLine(metrics.ConfusionMatrix.GetFormattedConfusionTable());
    Console.WriteLine("================================");
}

